WITH kept_keys AS (SELECT product_id, store_id FROM store_sales INTERSECT SELECT product_id, store_id FROM store_sales WHERE units BETWEEN 14 AND 29), verified AS (SELECT s.* FROM store_sales s JOIN kept_keys k ON s.product_id = k.product_id AND s.store_id = k.store_id) SELECT product_id, store_id, STDDEV_SAMP(units) AS units_stddev, APPROX_PERCENTILE(revenue, 0.9) AS revenue_p90, APPROX_PERCENTILE(units, 0.95) AS units_p95, CORR(revenue, units) AS corr_revenue_units, CORR(units, revenue) AS corr_units_revenue FROM verified GROUP BY GROUPING SETS ((product_id, store_id), (product_id), ()) HAVING units_stddev > 0;
